def is_balanced(text):
    pairs = {'(': ')', '[': ']', '{': '}'}
    stack = []
    for char in text:
        if char in pairs:
            stack.append(char)
        elif char in pairs.values():
            if not stack:
                return False
            open_char = stack.pop()
            if pairs[open_char] != char:
                return False
    return len(stack) == 0
